const $=s=>document.querySelector(s);const cards=$("#cards"),search=$("#search"),sector=$("#sector"),stage=$("#stage"),dialog=$("#detail");let picked=[];
for(const name of [...new Set(jobs.map(j=>j.sector))].sort((a,b)=>a.localeCompare(b,"es"))){const option=document.createElement("option");option.value=name;option.textContent=name;sector.append(option)}
const escaped=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
function card(j){return `<article class="card"><div class="card-top"><span class="job-icon" aria-hidden="true">${j.icon}</span><span class="sector-pill">${escaped(j.sector)}</span></div><h3>${escaped(j.name)}</h3><p>${escaped(j.summary)}</p><div class="card-bottom"><button class="text-button" data-open="${j.id}">Ver camino <span aria-hidden="true">↗</span></button><button class="compare-button ${picked.includes(j.id)?"selected":""}" data-pick="${j.id}" aria-pressed="${picked.includes(j.id)}" aria-label="${picked.includes(j.id)?"Quitar":"Comparar"} ${escaped(j.name)}">${picked.includes(j.id)?"✓ Añadida":"＋ Comparar"}</button></div></article>`}
function render(){const term=search.value.trim().toLocaleLowerCase("es");const list=jobs.filter(j=>(sector.value==="all"||sector.value===j.sector)&&(stage.value==="all"||j.stage.includes(stage.value))&&(!term||[j.name,j.sector,j.summary,...j.skills,...j.tasks,...j.routes].join(" ").toLocaleLowerCase("es").includes(term)));cards.innerHTML=list.map(card).join("");$("#count").textContent=`${list.length} ${list.length===1?"profesión":"profesiones"}`;$("#empty").hidden=list.length!==0;renderComparison()}
function sourceLinks(j){return j.src.map(k=>`<a href="${sources[k].url}" target="_blank" rel="noopener">${escaped(sources[k].label)} ↗</a>`).join("")}
function list(items){return `<ul>${items.map(x=>`<li>${escaped(x)}</li>`).join("")}</ul>`}
function openDetail(j){$("#detail-content").innerHTML=`<p class="eyebrow">${escaped(j.sector)} / FICHA ORIENTATIVA</p><div class="detail-heading"><span class="job-icon">${j.icon}</span><h2>${escaped(j.name)}</h2></div><p class="detail-summary">${escaped(j.summary)}</p><div class="detail-grid"><section><h3>¿Qué podrías hacer?</h3>${list(j.tasks)}</section><section><h3>Habilidades a desarrollar</h3>${list(j.skills)}</section><section class="wide"><h3>Caminos formativos posibles</h3>${list(j.routes)}${j.regulated?'<p class="warning">Profesión con requisitos de ejercicio: comprueba la normativa y el acceso oficial antes de elegir estudios.</p>':""}</section></div><div class="detail-sources"><strong>Fuentes para seguir investigando</strong>${sourceLinks(j)}<small>Enlaces generales, no validación específica de esta ficha. Contenido editorial inicial · septiembre 2026.</small></div>`;dialog.showModal()}
function renderComparison(){const area=$("#comparison");if(!picked.length){area.innerHTML='<p class="compare-placeholder">Selecciona dos profesiones con el botón “Comparar” de sus tarjetas.</p>';return}area.innerHTML=picked.map(id=>{const j=jobs.find(x=>x.id===id);return `<article class="compare-column"><div class="compare-title"><span class="job-icon">${j.icon}</span><div><small>${escaped(j.sector)}</small><h3>${escaped(j.name)}</h3></div><button data-pick="${j.id}" aria-label="Quitar ${escaped(j.name)} de la comparación">×</button></div><h4>Habilidades</h4>${list(j.skills)}<h4>Vías posibles</h4>${list(j.routes)}<button class="text-button" data-open="${j.id}">Abrir ficha ↗</button></article>`}).join("")+(picked.length===1?'<div class="compare-placeholder second">Elige una segunda profesión para poner los caminos lado a lado.</div>':"")}
document.addEventListener("click",e=>{const open=e.target.closest("[data-open]");if(open){openDetail(jobs.find(j=>j.id===open.dataset.open));return}const pick=e.target.closest("[data-pick]");if(pick){const id=pick.dataset.pick;picked=picked.includes(id)?picked.filter(x=>x!==id):picked.length<2?[...picked,id]:[picked[1],id];render()}});for(const control of [search,sector,stage])control.addEventListener(control===search?"input":"change",render);$("#close-detail").addEventListener("click",()=>dialog.close());dialog.addEventListener("click",e=>{if(e.target===dialog)dialog.close()});render();
